#!/usr/bin/env python3
"""Regenerate ground truth for CSX-062_Q1."""

from __future__ import annotations

import html
import json
import re
from pathlib import Path


TASK_ID = "CSX-062_Q1"
EVENT_ID = "CSX-062"
TARGET_FAMILY = "western_europe_rainfall_runoff_process_chain"
TASK_DIR = Path(__file__).resolve().parent
ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

SOURCE_FILES = {
    "anchor": "data/event_reports/event_reports_003_Locked_event_anchor_July_2021_Western_Europe_floods.json",
    "report": "data/other/other_003_03_ECMWF_-_Extreme_rain_in_Germany_and_Belgium_in_July_2021.html.html",
}


RUBRIC = [
    {
        "name": "Process-chain JSON",
        "points": 3,
        "description": (
            "Returns the requested JSON shape with target family, four process-chain stages, gate results, "
            "and final answer."
        ),
        "partial_credit": (
            "Award 1-2 points for the right answer with one missing stage."
        ),
    },
    {
        "name": "Input extraction and window",
        "points": 4,
        "description": (
            "Uses the 13 July 2021 06 UTC to 15 July 2021 06 UTC window with 104 mm area rainfall, "
            "20-25 percent runoff fraction, 271 mm Jalhay, 217 mm Spa, and German stations above 150 mm."
        ),
        "partial_credit": (
            "Award 1 point for each correct input family, with no more than 2 points if the 48-hour "
            "window is wrong."
        ),
    },
    {
        "name": "Runoff arithmetic",
        "points": 4,
        "description": (
            "Computes the runoff-equivalent range as 104 * 0.20 = 20.8 mm and 104 * 0.25 = 26.0 mm, "
            "then compares the lower value with the 20 mm threshold."
        ),
        "partial_credit": (
            "Award 2-3 points for the correct formula with rounding or percent-conversion mistakes; "
            "award 1 point for naming runoff conversion without computing the range."
        ),
    },
    {
        "name": "Station amplification",
        "points": 3,
        "description": (
            "Computes station-to-area ratios of 2.61 for Jalhay, 2.09 for Spa, and 1.44 for the German "
            "lower bound, then counts exactly two ratios at or above 2.0."
        ),
        "partial_credit": (
            "Award 1-2 points for two correct ratios or for correct ratios with the count rule applied incorrectly."
        ),
    },
    {
        "name": "Ordered process reasoning",
        "points": 3,
        "description": (
            "Explains the ordered rainfall input -> rapid runoff -> station amplification process rather than giving only a final label."
        ),
        "partial_credit": (
            "Award 1-2 points for correct gates without process ordering."
        ),
    },
    {
        "name": "Competing reading control",
        "points": 2,
        "description": (
            "Rejects a ponding-only or image-led interpretation by grounding the answer in rainfall conversion and station amplification."
        ),
        "partial_credit": "Award 1 point for one bounded rejection.",
    },
    {
        "name": "Concise bounds",
        "points": 1,
        "description": "Keeps the answer concise and does not add uncomputed loss or response claims.",
        "partial_credit": "No credit for unsupported impact expansion.",
    },
]


def load_json(relative_path: str) -> dict:
    return json.loads((PACKAGE_DIR / relative_path).read_text(encoding="utf-8"))


def clean_html(relative_path: str) -> str:
    raw = (PACKAGE_DIR / relative_path).read_text(encoding="utf-8", errors="replace")
    text = re.sub(r"<(script|style|nav|header|footer).*?</\1>", " ", raw, flags=re.S | re.I)
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text))


def require_match(pattern: str, text: str, description: str) -> re.Match[str]:
    match = re.search(pattern, text, flags=re.I | re.S)
    if not match:
        raise ValueError(f"Could not extract {description}")
    return match


def rounded_ratio(numerator: float, denominator: float) -> float:
    return round(numerator / denominator, 2)

def main() -> None:
    anchor = load_json(SOURCE_FILES["anchor"])
    report_text = clean_html(SOURCE_FILES["report"])

    area_48h_rain_mm = int(
        require_match(
            r"48.hour window starting at 06 UTC on 13 July 2021 has by far the heaviest precipitation, with\s+(\d+)\s+mm",
            report_text,
            "48-hour area rainfall",
        ).group(1)
    )
    jalhay_mm, spa_mm = [
        int(value)
        for value in require_match(
            r"Jalhay received\s+(\d+)\s+mm and Spa\s+(\d+)\s+mm",
            report_text,
            "Belgian station rainfall",
        ).groups()
    ]
    german_min_mm = int(
        require_match(
            r"German side measured more than\s+(\d+)\s+mm/48 h",
            report_text,
            "German station rainfall lower bound",
        ).group(1)
    )
    runoff_low_pct, runoff_high_pct = [
        int(value)
        for value in require_match(
            r"predicted up to\s+(\d+)\D+(\d+)% of the total rainfall",
            report_text,
            "rapid-runoff percentage range",
        ).groups()
    ]

    runoff_depth_range_mm = [
        round(area_48h_rain_mm * runoff_low_pct / 100, 2),
        round(area_48h_rain_mm * runoff_high_pct / 100, 2),
    ]
    station_to_area_ratios = {
        "jalhay": rounded_ratio(jalhay_mm, area_48h_rain_mm),
        "spa": rounded_ratio(spa_mm, area_48h_rain_mm),
        "german_min": rounded_ratio(german_min_mm, area_48h_rain_mm),
    }
    runoff_load_pass = runoff_depth_range_mm[0] >= 20
    station_amplification_count = sum(1 for value in station_to_area_ratios.values() if value >= 2.0)
    station_amplification_pass = station_amplification_count >= 2
    answer = "rapid_runoff_load_pass" if runoff_load_pass and station_amplification_pass else "rapid_runoff_load_fail"
    process_chain = [
        {
            "stage": "regional_rainfall_input",
            "computed_values": {"area_48h_rain_mm": area_48h_rain_mm},
            "process_role": "A 48-hour basin-scale rainfall load supplies the regional hydrologic input.",
        },
        {
            "stage": "rapid_runoff_conversion",
            "computed_values": {
                "runoff_fraction_range": [runoff_low_pct / 100, runoff_high_pct / 100],
                "runoff_depth_range_mm": runoff_depth_range_mm,
            },
            "process_role": "The documented rapid-runoff fraction converts the rainfall field into at least 20.8 mm of fast runoff depth.",
        },
        {
            "stage": "station_scale_amplification",
            "computed_values": {"station_to_area_ratios": station_to_area_ratios},
            "process_role": "Two Belgian station totals exceed twice the area rainfall, showing local amplification on top of the regional input.",
        },
        {
            "stage": "flood_process_label",
            "computed_values": {
                "runoff_load_pass": runoff_load_pass,
                "station_amplification_pass": station_amplification_pass,
            },
            "process_role": "The combined rainfall-runoff and station-amplification evidence supports the rapid runoff-load process label.",
        },
    ]

    primary_gt = {
        "target_family": TARGET_FAMILY,
        "process_chain": process_chain,
        "area_48h_rain_mm": area_48h_rain_mm,
        "runoff_depth_range_mm": runoff_depth_range_mm,
        "station_to_area_ratios": station_to_area_ratios,
        "gate_results": {
            "runoff_load_pass": runoff_load_pass,
            "station_amplification_pass": station_amplification_pass,
        },
        "answer": answer,
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": TARGET_FAMILY,
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": "July 2021 Western Europe floods",
            "event_window": (
                f"{anchor['temporal_window']['start_date']}_to_{anchor['temporal_window']['end_date']}"
            ),
            "calculation_window": "2021-07-13T06:00Z_to_2021-07-15T06:00Z",
            "inputs": {
                "area_48h_rain_mm": area_48h_rain_mm,
                "runoff_fraction_pct": [runoff_low_pct, runoff_high_pct],
                "station_48h_mm": {
                    "jalhay": jalhay_mm,
                    "spa": spa_mm,
                    "german_min": german_min_mm,
                },
            },
            "formulae": {
                "runoff_depth_mm": "area_48h_rain_mm * runoff_fraction_pct / 100",
                "station_to_area_ratio": "station_48h_mm / area_48h_rain_mm",
            },
            "thresholds": {
                "runoff_low_mm_min": 20,
                "station_ratio_min": 2.0,
                "station_ratio_count_min": 2,
            },
            "computed_interpretation": (
                "The pass state is driven by a 20.8-26.0 mm rapid-runoff depth and two station "
                "totals above twice the area-rain baseline."
            ),
        },
        "numeric_tolerances": {
            "area_48h_rain_mm": {"value": area_48h_rain_mm, "tolerance": 1},
            "runoff_low_mm": {"value": runoff_depth_range_mm[0], "tolerance": 0.1},
            "runoff_high_mm": {"value": runoff_depth_range_mm[1], "tolerance": 0.1},
            "jalhay_ratio": {"value": station_to_area_ratios["jalhay"], "tolerance": 0.02},
            "spa_ratio": {"value": station_to_area_ratios["spa"], "tolerance": 0.02},
            "german_min_ratio": {"value": station_to_area_ratios["german_min"], "tolerance": 0.02},
            "station_amplification_count": {"value": station_amplification_count, "tolerance": 0},
        },
        "rubric": {
            "total_points": 20,
            "criteria": RUBRIC,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": list(SOURCE_FILES.values()),
        },
    }

    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(computed_gt, ensure_ascii=True, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
